      'lc-schedule': (el) => { const x = St.get('landlordContracts', el.dataset.id); const rows0 = (x.priceSchedule || []).length ? x.priceSchedule : [{ from: F.addMonths(x.start, x.priceHoldMonths || 24), price: Math.round(x.rent * 1.05) }]; const row = (r, i) => `<tr><td>${U.date({ name: 'f_' + i, value: r.from, cls: 'sm' })}</td><td>${U.money({ name: 'p_' + i, value: r.price })}</td><td>${U.input({ name: 'n_' + i, value: r.note || '', cls: 'sm' })}</td></tr>`; const m = U.modal({ title: 'Lịch tăng giá – ' + x.code, sub: 'Mỗi dòng một mốc: từ ngày – giá mới (lưu lịch sử điều chỉnh giá)', body: `<table class="tbl compact"><thead><tr><th>Từ ngày</th><th>Giá mới</th><th>Ghi chú</th></tr></thead><tbody id="ps-body">${rows0.map(row).join('')}</tbody></table>` + U.btn({ label: 'Thêm mốc', icon: 'plus', size: 'btn-sm', cls: 'btn-ghost', act: 'add' }), footer: U.btn({ label: 'Hủy', act: 'c' }) + U.btn({ label: 'Lưu lịch', cls: 'btn-primary', act: 's' }) }); let n = rows0.length; U.bind(m.el, { c: () => m.close(), add: () => { m.el.querySelector('#ps-body').insertAdjacentHTML('beforeend', row({ from: '', price: '' }, n++)); }, s: () => { try { const d = m.data(); const list = Array.from({ length: n }, (_, i) => ({ from: d['f_' + i], price: d['p_' + i], note: d['n_' + i] })); X.savePriceSchedule(x.id, list); m.close(); TH.router.refresh(); } catch (e) { U.toast('err', 'Lỗi', e.message); } } }); },
