      more: (el) => { const x = St.get('landlordPayments', el.dataset.id); U.menu(el, [x.status !== 'paid' ? { label: 'Ghi nhận đã trả', icon: 'check', onClick: () => Fm.landlordPaid(x) } : { label: 'Đã thanh toán ' + F.date(x.paidDate), icon: 'check-circle', disabled: true }, { label: 'Nhắc thanh toán (Zalo/Email)', icon: 'send', p2: true, title: TH.phase.on(2) ? 'Tạo đợt Zalo sự kiện Đến kỳ trả chủ nhà' : 'Kênh nhắc chủ nhà chưa chốt – OI-03', onClick: () => { if (!TH.auth.can('zalo.send')) return U.toast('err', 'Không có quyền gửi Zalo', 'Chỉ Admin được tạo đợt gửi (zalo.send)'); const ev = St.one('zaloEvents', z => z.key === 'landlord_due'); if (ev && !ev.enabled) return U.toast('warn', 'Rule "Đến kỳ trả chủ nhà" đang tắt', 'Bật tại Cấu hình Zalo trước (FR-ZAL-01)'); const tpl = Q.template(ev.templateId); const b = St.add('zaloBatches', { code: St.nextCode('zaloBatches', 'ZL-' + periodCode(F.period(x.dueDate)) + '-', 3), name: 'Nhắc trả chủ nhà ' + x.periodLabel, eventKey: 'landlord_due', sourceKey: 'landlord_due', audience: 'Chủ nhà', plannedCount: 1, sentCount: 0, failedCount: 0, sentAt: null, createdBy: TH.auth.user().id, status: 'draft', templateId: tpl.id, scopeLabel: Q.building(x.buildingId).name, period: F.period(x.dueDate), sendMode: 'now', rules: 'Nhắc kỳ thanh toán chủ nhà', phase: 2, log: [] }); const ll = St.get('landlords', x.landlordId) || {}; St.add('zaloMessages', { batchId: b.id, tenantId: null, landlordId: x.landlordId, roomId: null, buildingId: x.buildingId, invoiceId: null, channel: 'Zalo', templateCode: tpl.code, status: 'queued', errorCode: '', sentAt: null, phone: ll.phone || '', content: Q.renderTemplate(tpl.body, Q.templateCtx(null, { name: ll.name }, { buildingId: x.buildingId, amount: x.amount, due: x.dueDate })), amountAtSend: x.amount, retryOfId: null, attempt: 1, recipientName: ll.name }); St.audit('create', 'zaloBatch', b.id, 'Nhắc trả chủ nhà ' + b.code); X.startBatch(b.id); U.toast('ok', 'Đã tạo đợt nhắc chủ nhà ' + b.code); TH.go('#/zalo/batches/' + b.id); } }]); },
